def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    volume = (s.get('lattice') or {}).get('volume_A3')
    total = 0.0
    spheres = 0.0
    for site in sites:
        o = max(0.0, site.get('occupancy', 1.0) or 0.0)
        total += o
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        if r is not None and r > 0:
            spheres += o * r ** 3
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        if v is None or v <= 0:
            return 0.0
        volume = v * total
    if volume <= 0:
        return 0.0
    return 4.0 * pi * spheres / (3.0 * volume)

def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    composition = s.get('composition') or {}
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    electrons = 0.0
    covered = 0.0
    for element, fraction in composition.items():
        valence = (props.get(element) or {}).get('valence_electrons')
        if fraction is not None and fraction > 0 and valence is not None:
            electrons += fraction * max(0.0, valence)
            covered += fraction
    if covered <= 0:
        return 0.0
    return log1p(electrons / (covered * v))

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    neighbors = s.get('neighbors') or []
    n = len(sites)
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    values = [0.0] * len(neighbors)
    count = 0
    for edge in neighbors:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                values[count] = d / (a + b)
                count += 1
    if count == 0:
        return 0.0
    values = sorted(values[:count])
    x = 0.1 * (count - 1)
    k = int(x)
    return values[k] + (x - k) * (values[min(k + 1, count - 1)] - values[k])

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    nearest = [inf] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                nearest[i] = min(nearest[i], d / (a + b))
    value = 0.0
    weight = 0.0
    for i in range(n):
        o = max(0.0, sites[i].get('occupancy', 1.0) or 0.0)
        if nearest[i] < inf:
            value += o * nearest[i]
            weight += o
    return value / weight if weight > 0 else 0.0

