                value += occ[i] * occ[j] * overlap * overlap
    return value / (2.0 * total)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    en = [(props.get(t.get('element')) or {}).get('eneg') for t in sites]
    nearest = [inf] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[j] > 0 and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    value = 0.0
    total = 0.0
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and nearest[i] < inf:
            if en[i] is not None and en[j] is not None:
                ratio = d / nearest[i]
                if ratio <= 1.7:
                    w = occ[i] * occ[j] * exp(1.0 - ratio ** 6)
                    value += w * (en[i] - en[j]) ** 2
                    total += w
    return sqrt(max(0.0, value / total)) if total > 0 else 0.0

