def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    en = [(props.get(t.get('element')) or {}).get('eneg') for t in sites]
    nearest = [inf] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[j] > 0 and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    weights = [0.0] * n
    sums = [0.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and nearest[i] < inf:
            if en[j] is not None:
                ratio = d / nearest[i]
                if ratio <= 1.7:
                    w = occ[j] * exp(1.0 - ratio ** 6)
                    weights[i] += w
                    sums[i] += w * en[j]
    value = 0.0
    total = 0.0
    for i in range(n):
        if en[i] is not None and weights[i] > 0:
            value += occ[i] * (en[i] - sums[i] / weights[i]) ** 2
            total += occ[i]
    return sqrt(max(0.0, value / total)) if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    nearest = [inf] * n
    same = [6.0] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[j] > 0 and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
            if sites[i].get('element') == sites[j].get('element'):
                same[i] = min(same[i], d)
    value = 0.0
    total = 0.0
    for i in range(n):
        if nearest[i] < inf:
            value += occ[i] * log(max(1.0, same[i] / nearest[i]))
            total += occ[i]
    return value / total if total > 0 else 0.0

